/* ============ SpectroForge 内核 ============
   纯函数：迭代 radix-2 FFT、波形峰值、频谱图。 */
var SpectroForgePure = (function(){
  // 原地迭代 FFT（Cooley-Tukey），re/im 等长且为 2 的幂。
  function fft(re, im){
    var n = re.length;
    for(var i=1, j=0; i<n; i++){
      var bit = n>>1;
      for(; j & bit; bit>>=1) j ^= bit;
      j ^= bit;
      if(i < j){ var tr=re[i]; re[i]=re[j]; re[j]=tr; var ti=im[i]; im[i]=im[j]; im[j]=ti; }
    }
    for(var len=2; len<=n; len<<=1){
      var ang = -2*Math.PI/len, wr=Math.cos(ang), wi=Math.sin(ang);
      for(var i2=0; i2<n; i2+=len){
        var cwr=1, cwi=0;
        for(var k=0; k<len/2; k++){
          var a=i2+k, b=i2+k+len/2;
          var tr = re[b]*cwr - im[b]*cwi, ti = re[b]*cwi + im[b]*cwr;
          re[b] = re[a]-tr; im[b] = im[a]-ti;
          re[a] = re[a]+tr; im[a] = im[a]+ti;
          var ncwr = cwr*wr - cwi*wi; cwi = cwr*wi + cwi*wr; cwr = ncwr;
        }
      }
    }
  }
  function mag(re, im){ var o=[]; for(var i=0;i<re.length;i++) o.push(Math.sqrt(re[i]*re[i]+im[i]*im[i])); return o; }

  function computeWaveform(samples, buckets){
    buckets = buckets || 100;
    var out=[], n=samples.length;
    if(n===0) return [];
    var per = n/buckets;
    for(var i=0;i<buckets;i++){
      var s=Math.floor(i*per), e=Math.min(n, Math.floor((i+1)*per)), mx=0;
      for(var j=s;j<e;j++){ var v=Math.abs(samples[j]); if(v>mx) mx=v; }
      out.push(mx);
    }
    return out;
  }

  function computeSpectrogram(samples, sampleRate, opts){
    opts = opts || {};
    var fftSize = opts.fftSize || 1024;
    var hop = opts.hop || (fftSize>>1);
    var win = opts.window || 'hann';
    var n = samples.length;
    if(n < fftSize) return {error:'音频太短，至少需要 '+fftSize+' 个采样点'};
    if((fftSize & (fftSize-1)) !== 0) return {error:'fftSize 必须是 2 的幂'};
    var w = new Array(fftSize);
    for(var i=0;i<fftSize;i++) w[i] = (win==='hann') ? (0.5 - 0.5*Math.cos(2*Math.PI*i/(fftSize-1))) : 1;
    var bins = fftSize>>1;
    var cols = Math.floor((n - fftSize)/hop) + 1;
    var data = [];
    for(var c=0;c<cols;c++){
      var off = c*hop, re=new Array(fftSize), im=new Array(fftSize);
      for(var i2=0;i2<fftSize;i2++){ re[i2] = samples[off+i2]*w[i2]; im[i2]=0; }
      fft(re, im);
      var col=[];
      for(var b=0;b<bins;b++) col.push(Math.sqrt(re[b]*re[b]+im[b]*im[b]) / fftSize);
      data.push(col);
    }
    return { sampleRate:sampleRate, fftSize:fftSize, hop:hop, bins:bins, cols:cols, data:data };
  }

  function freqAt(bin, sampleRate, fftSize){ return bin * sampleRate / fftSize; }
  function binAt(freq, sampleRate, fftSize){ return Math.round(freq * fftSize / sampleRate); }

  return { fft:fft, mag:mag, computeWaveform:computeWaveform,
           computeSpectrogram:computeSpectrogram, freqAt:freqAt, binAt:binAt };
})();
if (typeof module !== 'undefined' && module.exports) module.exports = SpectroForgePure;
if (typeof window !== 'undefined') window.SpectroForgePure = SpectroForgePure;
